#!/usr/bin/env python3
"""Offline gh stand-in for the sandbox: serves recorded PR data from bin/data."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
DATA = os.path.join(HERE, "data")
POSTED = os.path.join(os.path.dirname(HERE), "posted.log")
args = sys.argv[1:]


def load(name):
    path = os.path.join(DATA, name)
    if not os.path.exists(path):
        return None
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def out(text, code=0):
    sys.stdout.write(text if text.endswith("\n") else text + "\n")
    sys.exit(code)


def fail(message, code=1):
    sys.stderr.write(message + "\n")
    sys.exit(code)


def flag(name, default=None):
    for index, arg in enumerate(args):
        if arg == name and index + 1 < len(args):
            return args[index + 1]
    return default


def positional():
    skip = {"--json", "--jq", "-X", "--method", "-f", "-F", "--field", "--raw-field", "-H", "--header", "-q"}
    found = []
    index = 0
    while index < len(args):
        if args[index] in skip:
            index += 2
            continue
        if not args[index].startswith("-"):
            found.append(args[index])
        index += 1
    return found


def jq(value, expression):
    for part in [p for p in expression.strip(".").split(".") if p]:
        value = value[part]
    return value if isinstance(value, str) else json.dumps(value)


if (load("mode.txt") or "").strip() == "missing" and args[:1] in (["pr"], ["api"]) and "user" not in args:
    fail("GraphQL: Could not resolve to a PullRequest with the number requested. (repository.pullRequest)")

if args[:2] == ["pr", "checks"]:
    raw = load("checks.json") or "[]"
    checks = json.loads(raw)
    if "--json" in args:
        out(json.dumps(checks), 1 if any(c.get("bucket") == "fail" for c in checks) else 0)
    for check in checks:
        out_line = "\t".join([check["name"], check["bucket"], "1m", check["link"]])
        sys.stdout.write(out_line + "\n")
    sys.exit(0)

if args[:2] == ["pr", "view"]:
    number = int(load("number.txt") or "0")
    view = json.loads(load("pr_view.json") or "{}")
    view["number"] = number
    fields = (flag("--json") or "number").split(",")
    picked = {key: view.get(key) for key in fields}
    expression = flag("--jq") or flag("-q")
    out(jq(picked, expression) if expression else json.dumps(picked))

if args[:2] == ["repo", "view"]:
    expression = flag("--jq") or flag("-q")
    repo = {"nameWithOwner": "acme/widgets"}
    out(jq(repo, expression) if expression else json.dumps(repo))

if args[:2] == ["auth", "status"]:
    out("Logged in to github.com as journey-user")

if args[:2] == ["run", "view"]:
    run_id = positional()[2] if len(positional()) > 2 else ""
    log = load("log-%s.txt" % run_id)
    if log is None:
        fail("log not found")
    out(log)

if args[:1] == ["api"]:
    rest = positional()[1:]
    endpoint = rest[0] if rest else ""
    method = (flag("-X") or flag("--method") or "GET").upper()
    fields = [args[i + 1] for i, a in enumerate(args) if a in ("-f", "-F", "--field", "--raw-field") and i + 1 < len(args)]
    if endpoint == "user":
        user = {"login": "journey-user"}
        expression = flag("--jq") or flag("-q")
        out(jq(user, expression) if expression else json.dumps(user))
    if endpoint == "graphql":
        if any("mutation" in f for f in fields):
            with open(POSTED, "a", encoding="utf-8") as handle:
                handle.write("GRAPHQL MUTATION %s\n" % " ".join(fields))
            out(json.dumps({"data": {"resolveReviewThread": {"thread": {"isResolved": True}}}}))
        out(load("threads.json") or "{}")
    if method in ("POST", "PUT", "PATCH", "DELETE") or any(f.startswith("body=") for f in fields):
        with open(POSTED, "a", encoding="utf-8") as handle:
            handle.write("%s %s %s\n" % (method, endpoint, " ".join(fields)))
        out(json.dumps({"id": 900001, "html_url": "https://github.com/acme/widgets/pull/1#issuecomment-900001"}))
    if "/pulls/" in endpoint and endpoint.endswith("/comments"):
        out(load("comments.json") or "[]")
    if "/pulls/" in endpoint and endpoint.endswith("/reviews"):
        out(load("reviews.json") or "[]")
    fail("gh: Not Found (HTTP 404)")

fail("gh: command not available in this sandbox: %s" % " ".join(args))

